// Filtra temas tributarios, deduplica contra ejecuciones previas
// y mapea al esquema que consume el frontend (RADAR_DATA).
const KEYWORDS = /(sunat|igv|impuesto|tribut|renta|pdt\s?\d|detracci|percepci|retenci|decreto supremo|decreto legislativo|normas legales|mef|sbs)/i;
const ALTO = /(decreto supremo|decreto legislativo|\bley\b|igv|impuesto a la renta|amnist)/i;

const store = $getWorkflowStaticData('global');
const seen = new Set(store.seenLinks || []);

const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const link = j.link || '';
  // Google News agrega " - Medio" al final del título
  const titulo = String(j.title || '').replace(/\s+-\s+[^-]+$/, '').trim();
  if (!link || !titulo || !KEYWORDS.test(titulo)) continue;
  if (seen.has(link)) continue;

  seen.add(link);
  out.push({
    json: {
      titulo,
      resumen: String(j.contentSnippet || '').slice(0, 220),
      fecha: String(j.isoDate || new Date().toISOString()).slice(0, 10),
      impacto: ALTO.test(titulo) ? 'alto' : 'medio',
      fuente: 'elperuano',
      link,
      createdAt: Date.now()
    }
  });
}

// Conserva solo los últimos 500 links vistos
store.seenLinks = Array.from(seen).slice(-500);
return out;
